const m=new Map([["a",1],["b",2],["c",3]]),mapPairs=[];for(const[s,o]of m)mapPairs.push(s+":"+o);print("map:",mapPairs.join(","));const s=new Set([5,5,6,7,7,7]),setVals=[];for(const o of s)setVals.push(o);print("set (dedup):",setVals.join(","));const custom={from:1,to:5,[Symbol.iterator](){let s=this.from;const o=this.to;return{next:()=>s<=o?{value:s++,done:!1}:{value:void 0,done:!0}}}},customVals=[];for(const s of custom)customVals.push(s);print("custom range:",customVals.join(","));